static const char *regtrace_irq_name(struct platform_device *pdev, unsigned int idx)
{
    const char *name = pdev ? pdev->name : NULL;

    if (name) {
        if (!strcmp(name, "isp-m0"))
            return regtrace_irq_name_core;
        if (!strcmp(name, "isp-fs"))
            return regtrace_irq_name_fs;
        if (!strcmp(name, "isp-w02"))
            return regtrace_irq_name_vic;
        if (!strcmp(name, "isp-w01")) {
            if (idx == 0)
                return regtrace_irq_name_csi0;
            return regtrace_irq_name_csi1;
        }
    }

    switch (idx) {
    case 0:
        return regtrace_irq_name_0;
    case 1:
        return regtrace_irq_name_1;
    case 2:
        return regtrace_irq_name_2;
    case 3:
        return regtrace_irq_name_3;
    default:
        return "tx-isp-irq";
    }
}

static int regtrace_irq_slot_valid(uintptr_t base, uint32_t idx)
{
    uint32_t count;
    uint32_t irq;

    if (!base || idx >= REGTRACE_MAX_IRQS_PER_DEVICE)
        return 0;

    count = *(uint32_t *)(base + REGTRACE_IRQ_COUNT_OFF);
    if (count == 0 || count > REGTRACE_MAX_IRQS_PER_DEVICE || idx >= count)
        return 0;

    irq = *(uint32_t *)(base + REGTRACE_IRQ_SLOT_IRQ_OFF + (idx * sizeof(uint32_t)));
    return irq > 0;
}

static uintptr_t regtrace_irq_table_base(uintptr_t arg, uint32_t idx)
{
    uintptr_t nested;

    if (!arg)
        return 0;

    nested = arg + REGTRACE_IRQ_TABLE_SUBDEV_OFF;
    if (regtrace_irq_slot_valid(nested, idx))
        return nested;

    if (regtrace_irq_slot_valid(arg, idx))
        return arg;

    return arg;
}

