static void regtrace_init_platform_device(struct platform_device *pdev,
                                          const char *name,
                                          struct resource *resources,
                                          unsigned int num_resources,
                                          void *platform_data)
{
    pdev->name = name;
    pdev->id = -1;
    pdev->num_resources = num_resources;
    pdev->resource = resources;
    pdev->dev.parent = &tx_isp_platform_device.dev;
    pdev->dev.dma_mask = &tx_isp_platform_device_dma_mask;
    pdev->dev.coherent_dma_mask = 0xffffffff;
    pdev->dev.release = tx_isp_platform_device_platform_release;
    pdev->dev.platform_data = platform_data;
}

static struct platform_device *regtrace_child_platform_device(unsigned int slot)
{
    switch (slot) {
    case 0:
        return &tx_isp_csi_platform_device;
    case 1:
        return &tx_isp_vic_platform_device;
    case 2:
        return &tx_isp_vin_platform_device;
    case 3:
        return &tx_isp_fs_platform_device;
    case 4:
        return &tx_isp_core_platform_device;
    default:
        return NULL;
    }
}

static void regtrace_unregister_child_platform_devices(void)
{
    int i;

    for (i = ARRAY_SIZE(regtrace_child_device_registered) - 1; i >= 0; i--) {
        struct platform_device *pdev;

        if (!regtrace_child_device_registered[i])
            continue;

        pdev = regtrace_child_platform_device(i);
        if (pdev) {
            printk(KERN_INFO "tx_isp_t40_recovered: unregister child platform device %s\n",
                   dev_name(&pdev->dev));
            platform_device_unregister(pdev);
        }
        regtrace_child_device_registered[i] = 0;
    }
}

static int regtrace_register_child_platform_devices(void)
{
    unsigned int i;
    int ret;

    for (i = 0; i < ARRAY_SIZE(regtrace_child_device_registered); i++) {
        struct platform_device *pdev = regtrace_child_platform_device(i);

        if (!pdev || regtrace_child_device_registered[i])
            continue;

        ret = platform_device_register(pdev);
        if (ret) {
            printk(KERN_ERR "tx_isp_t40_recovered: child platform device %s failed: %d\n",
                   pdev->name, ret);
            regtrace_unregister_child_platform_devices();
            return ret;
        }

        regtrace_child_device_registered[i] = 1;
        printk(KERN_INFO "tx_isp_t40_recovered: registered child platform device %s\n",
               dev_name(&pdev->dev));
    }

    return 0;
}

static int regtrace_tx_isp_parent_probe(struct platform_device *pdev)
{
    printk(KERN_INFO "tx_isp_t40_recovered: parent probe %s using controlled child registration\n",
           dev_name(&pdev->dev));
    platform_set_drvdata(pdev, &regtrace_tx_isp_pdata);
    return regtrace_register_child_platform_devices();
}

static int regtrace_tx_isp_parent_remove(struct platform_device *pdev)
{
    printk(KERN_INFO "tx_isp_t40_recovered: parent remove %s\n",
           dev_name(&pdev->dev));
    regtrace_unregister_child_platform_devices();
    platform_set_drvdata(pdev, NULL);
    return 0;
}

static void regtrace_init_platform_driver(struct platform_driver *drv,
                                          const char *name,
                                          int (*probe)(struct platform_device *),
                                          int (*remove)(struct platform_device *))
{
    memset(drv, 0, sizeof(*drv));
    drv->probe = probe;
    drv->remove = remove;
    drv->driver.name = name;
    drv->driver.owner = THIS_MODULE;
}

static void regtrace_setup_platform_bus_data(void)
{
    regtrace_tx_isp_entities[0] = &tx_isp_core_platform_device;
    regtrace_tx_isp_entities[1] = &tx_isp_vic_platform_device;
    regtrace_tx_isp_entities[2] = &tx_isp_csi_platform_device;
    regtrace_tx_isp_entities[3] = &tx_isp_vin_platform_device;
    regtrace_tx_isp_entities[4] = &tx_isp_fs_platform_device;
    regtrace_tx_isp_pdata.entity_num = ARRAY_SIZE(regtrace_tx_isp_entities);
    regtrace_tx_isp_pdata.entities = regtrace_tx_isp_entities;

    tx_isp_platform_device.id = -1;
    tx_isp_platform_device.dev.platform_data = &regtrace_tx_isp_pdata;
    tx_isp_platform_device.dev.release = tx_isp_platform_device_platform_release;

    memset(regtrace_tx_isp_vic_pdata, 0, sizeof(regtrace_tx_isp_vic_pdata));
    regtrace_tx_isp_vic_pdata[0] = 1;
    regtrace_tx_isp_vic_pdata[12] = ARRAY_SIZE(regtrace_tx_isp_vic_pads) / 2;
    *(const void **)((char *)regtrace_tx_isp_vic_pdata + 16) =
        (const void *)regtrace_tx_isp_vic_pads;

    memset(regtrace_tx_isp_vin_pdata, 0, sizeof(regtrace_tx_isp_vin_pdata));
    regtrace_tx_isp_vin_pdata[0] = 1;
    regtrace_tx_isp_vin_pdata[12] = ARRAY_SIZE(regtrace_tx_isp_vin_pads) / 2;
    *(const void **)((char *)regtrace_tx_isp_vin_pdata + 16) =
        (const void *)regtrace_tx_isp_vin_pads;

    regtrace_init_platform_device(&tx_isp_core_platform_device, "isp-m0",
                                  (struct resource *)tx_isp_core_resource, 2,
                                  tx_isp_subdev_ispcore);
    regtrace_init_platform_device(&tx_isp_vic_platform_device, "isp-w02",
                                  (struct resource *)tx_isp_vic_resource, 4,
                                  regtrace_tx_isp_vic_pdata);
    regtrace_init_platform_device(&tx_isp_csi_platform_device, "isp-w01",
                                  (struct resource *)tx_isp_csi_resource, 2,
                                  tx_isp_widget_csi);
    regtrace_init_platform_device(&tx_isp_vin_platform_device, "isp-w00",
                                  NULL, 0, regtrace_tx_isp_vin_pdata);
    regtrace_init_platform_device(&tx_isp_fs_platform_device, "isp-fs",
                                  (struct resource *)tx_isp_fs_resource, 1,
                                  tx_isp_subdev_framesource);

    regtrace_init_platform_driver(&tx_isp_vin_driver, "isp-w00",
                                  tx_isp_vin_probe, tx_isp_vin_remove);
    regtrace_init_platform_driver(&tx_isp_csi_driver, "isp-w01",
                                  tx_isp_csi_probe, tx_isp_csi_remove);
    regtrace_init_platform_driver(&tx_isp_vic_driver, "isp-w02",
                                  tx_isp_vic_probe, tx_isp_vic_remove);
    regtrace_init_platform_driver(&tx_isp_core_driver, "isp-m0",
                                  tx_isp_core_probe, tx_isp_core_remove);
    regtrace_init_platform_driver(&tx_isp_fs_driver, "isp-fs",
                                  tx_isp_fs_probe, tx_isp_fs_remove);
    regtrace_init_platform_driver(&regtrace_tx_isp_platform_driver, "tx-isp",
                                  regtrace_tx_isp_parent_probe,
                                  regtrace_tx_isp_parent_remove);
}

static int regtrace_register_platform_driver_slot(unsigned int slot,
                                                  struct platform_driver *drv)
{
    int ret;

    if (regtrace_child_driver_registered[slot])
        return 0;

    ret = platform_driver_register(drv);
    if (!ret) {
        regtrace_child_driver_registered[slot] = 1;
        printk(KERN_INFO "tx_isp_t40_recovered: registered child driver %s\n",
               drv->driver.name);
    } else {
        printk(KERN_ERR "tx_isp_t40_recovered: child driver %s failed: %d\n",
               drv->driver.name, ret);
    }
    return ret;
}

static void regtrace_unregister_real_platforms(void)
{
    int i;
    struct platform_driver *drivers[] = {
        &tx_isp_vin_driver,
        &tx_isp_csi_driver,
        &tx_isp_vic_driver,
        &tx_isp_core_driver,
        &tx_isp_fs_driver,
    };

    regtrace_unregister_child_platform_devices();

    if (regtrace_parent_device_registered) {
        platform_device_unregister(&tx_isp_platform_device);
        regtrace_parent_device_registered = 0;
    }
    if (regtrace_parent_driver_registered) {
        platform_driver_unregister(&regtrace_tx_isp_platform_driver);
        regtrace_parent_driver_registered = 0;
    }

    for (i = ARRAY_SIZE(drivers) - 1; i >= 0; i--) {
        if (regtrace_child_driver_registered[i]) {
            platform_driver_unregister(drivers[i]);
            regtrace_child_driver_registered[i] = 0;
        }
    }
}

static int regtrace_register_real_platforms(void)
{
    int ret;

    regtrace_setup_platform_bus_data();

    ret = regtrace_register_platform_driver_slot(0, &tx_isp_vin_driver);
    if (ret)
        goto fail;
    ret = regtrace_register_platform_driver_slot(1, &tx_isp_csi_driver);
    if (ret)
        goto fail;
    ret = regtrace_register_platform_driver_slot(2, &tx_isp_vic_driver);
    if (ret)
        goto fail;
    ret = regtrace_register_platform_driver_slot(3, &tx_isp_core_driver);
    if (ret)
        goto fail;
    ret = regtrace_register_platform_driver_slot(4, &tx_isp_fs_driver);
    if (ret)
        goto fail;

    ret = platform_driver_register(&regtrace_tx_isp_platform_driver);
    if (ret)
        goto fail;
    regtrace_parent_driver_registered = 1;
    printk(KERN_INFO "tx_isp_t40_recovered: registered parent driver %s\n",
           regtrace_tx_isp_platform_driver.driver.name);

    ret = platform_device_register(&tx_isp_platform_device);
    if (ret)
        goto fail;
    regtrace_parent_device_registered = 1;

    printk(KERN_INFO "tx_isp_t40_recovered: registered real tx-isp platform path\n");
    return 0;

fail:
    printk(KERN_ERR "tx_isp_t40_recovered: real platform registration failed: %d\n", ret);
    regtrace_unregister_real_platforms();
    return ret;
}
